/* hrtim_pwm_20khz.c - STM32H7 LL + HRTIM PWM */
#include "stm32h7xx.h"
#define HRTIM_PERIOD ((84UL * 1000U) / 20U)
typedef struct {
    HRTIM_TypeDef *instance;
    uint32_t timer_id;
    uint16_t current_duty;
    uint32_t period;
} HrtimPwmHandle_t;
static HrtimPwmHandle_t g_hrtim_pwm = {0};

void HrtimPwm_Init(void) {
    LL_AHB1_GRP1_EnableClock(LL_AHB1_GRP1_PERIPH_HRTIM);
    g_hrtim_pwm.instance = HRTIM;
    g_hrtim_pwm.instance->GCR |= HRTIM_GCR_HRST;
    g_hrtim_pwm.instance->SCR = 0xFFFFFFFF;
    g_hrtim_pwm.instance->Timer[HRTIM_TIMER_ID].TCM = HRTIM_TIMCM_PWM1;
    g_hrtim_pwm.period = HRTIM_PERIOD;
    g_hrtim_pwm.instance->Timer[HRTIM_TIMER_ID].RLR = HRTIM_PERIOD;
    g_hrtim_pwm.instance->Timer[HRTIM_TIMER_ID].CCR1 = HRTIM_PERIOD / 2;
    g_hrtim_pwm.instance->SEER = (1 << HRTIM_TIMER_ID);
    g_hrtim_pwm.instance->EOTR = (1 << HRTIM_OUTPUT_PIN);
    g_hrtim_pwm.instance->STR = (1 << HRTIM_TIMER_ID);
}

void HrtimPwm_SetDuty(uint8_t duty_pct) {
    if (duty_pct > 100) duty_pct = 100;
    uint32_t new_ccr = (g_hrtim_pwm.period * duty_pct) / 100;
    g_hrtim_pwm.instance->Timer[g_hrtim_pwm.timer_id].CCR1 = new_ccr;
    g_hrtim_pwm.current_duty = duty_pct;
}

__attribute__((interrupt)) void HRTIM_IRQHandler(void) {
    uint32_t s = g_hrtim_pwm.instance->SCFR;
    g_hrtim_pwm.instance->SCCR = s;
    g_hrtim_pwm.instance->SCR = s;
}

/* 陷阱 1：错误的使能顺序 */
void pwm_wrong_order(void) {
    LL_HRTIM_EnableTimer(HRTIM, HRTIM_TIMER_ID_TIM2);
    HRTIM->TIM2.RLR = 4200;
    HRTIM->TIM2.CCR1 = 2100; /* 毛刺！ */
}

/* 陷阱 1：正确的顺序 */
void pwm_correct_order(void) {
    HRTIM->TIM2.RLR = 4200;
    HRTIM->TIM2.CCR1 = 2100;
    LL_HRTIM_EnableTimer(HRTIM, HRTIM_TIMER_ID_TIM2); /* 安全 */
}

/* 陷阱 2：不清除标志 */
void trap_isr_bad(void) {
    uint32_t s = HRTIM->SCFR; /* 只读不清除 */
}

/* 陷阱 2：正确清除 */
void trap_isr_good(void) {
    uint32_t s = HRTIM->SCFR;
    HRTIM->SCCR = s; /* 写 1 清零 */
    HRTIM->SCR = s;
}

/* 改进前：裸寄存器混写（反模式） */
#define PWM_FREQ_DIV 16666
#define DUTY_MAX 8000

void legacy_main_loop(void) {
    static uint16_t duty = 0;
    for (volatile int i = 0; i < PWM_FREQ_DIV; i++);
    if (duty < DUTY_MAX) {
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_0, GPIO_PIN_SET);
    } else {
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_0, GPIO_PIN_RESET);
    }
    duty += 1;
    if (duty >= DUTY_MAX) duty = 0;
}

/* 改进后：分层 ADT 驱动 */
typedef struct {
    HRTIM_HandleTypeDef *hhrtim;
    uint32_t timer_id;
    uint32_t period_ticks;
    uint32_t current_duty;
    bool soft_start_active;
} PwmHandle_t;

PwmStatus_t pwm_init(PwmHandle_t *h, HRTIM_HandleTypeDef *hhrtim,
                     uint32_t tim_id, uint32_t freq_hz) {
    memset(h, 0, sizeof(PwmHandle_t));
    h->hhrtim = hhrtim;
    h->timer_id = tim_id;
    h->period_ticks = 84000000U / freq_hz;
    return PWM_OK;
}

PwmStatus_t pwm_set_duty(PwmHandle_t *h, uint32_t pct) {
    if (h->soft_start_active) return PWM_ERR_BUSY;
    uint32_t duty = (h->period_ticks * pct) / 100;
    h->current_duty = duty;
    h->hhrtim->Instance->tim[h->timer_id].CCR1 = duty;
    return PWM_OK;
}
